<script>
document.getElementById('editContentModal')?.addEventListener('show.bs.modal', (event) => {
    const button = event.relatedTarget;
    const form = document.querySelector('[data-edit-content-form]');
    form.action = button.dataset.editUrl;
    form.elements.type.value = button.dataset.editType;
    form.elements.title.value = button.dataset.editTitle;
    form.elements.customer_name.value = button.dataset.editCustomer;
    form.elements.slug.value = button.dataset.editSlug;
    form.elements.excerpt.value = button.dataset.editExcerpt;
    form.elements.body.value = button.dataset.editBody;
    form.elements.quote.value = button.dataset.editQuote;
    form.elements.category.value = button.dataset.editCategory;
    form.elements.tags.value = button.dataset.editTags;
    form.elements.meta_keywords.value = button.dataset.editKeywords;
    form.elements.status.value = button.dataset.editStatus;
    form.elements.meta_title.value = button.dataset.editMetaTitle;
    form.elements.meta_description.value = button.dataset.editMetaDescription;
});
</script>
